<?php require_once __DIR__.'/includes/config.php';require_once __DIR__.'/includes/plan_limits.php';require_login();require_permission('products');$uid=(int)$_SESSION['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'add';if($action==='add'){$limits=kasuwalink_plan_limits($pdo,$uid);$countQ=$pdo->prepare('SELECT COUNT(*) FROM products WHERE user_id=?');$countQ->execute([$uid]);$productCount=(int)$countQ->fetchColumn();if($limits['product_limit']>0 && $productCount >= $limits['product_limit']){$errors[]='Your '.ucfirst($limits['plan']).' plan product limit has been reached. Upgrade your plan or remove an unused product.';}$name=trim($_POST['name']??'');$sku=trim($_POST['sku']??'')?:null;$cost=filter_var($_POST['cost_price']??null,FILTER_VALIDATE_FLOAT);$price=filter_var($_POST['selling_price']??null,FILTER_VALIDATE_FLOAT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$threshold=filter_var($_POST['low_stock_threshold']??5,FILTER_VALIDATE_INT);if($name===''||mb_strlen($name)>160)$errors[]='Enter a product name.';if($cost===false||$cost<0||$price===false||$price<0)$errors[]='Enter valid non-negative prices.';if($qty===false||$qty<0||$threshold===false||$threshold<0)$errors[]='Quantity and stock threshold must be whole numbers of zero or more.';if(!$errors){try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO products(user_id,name,sku,cost_price,selling_price,quantity,low_stock_threshold) VALUES(?,?,?,?,?,?,?)');$q->execute([$uid,$name,$sku,$cost,$price,$qty,$threshold]);$pid=(int)$pdo->lastInsertId();if($qty>0){$m=$pdo->prepare("INSERT INTO inventory_movements(user_id,product_id,product_name,movement_type,quantity_change,quantity_before,quantity_after,reference_type,reference_id,note) VALUES(?,?,?,'opening_stock',?,0,?,'product',?,?)");$m->execute([$uid,$pid,$name,$qty,$qty,$pid,'Initial stock when product was created']);}audit_log($pdo,'product_created','product',$pid,'Product '.$name.'; opening quantity '.(int)$qty);$pdo->commit();flash('Product added successfully.');redirect('products.php');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex instanceof PDOException && $ex->getCode()==='23000'?'That SKU already exists in your business.':'Unable to save product.';}}}elseif($action==='delete'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($id){$q=$pdo->prepare('SELECT COUNT(*) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE si.product_id=? AND s.user_id=?');$q->execute([$id,$uid]);if((int)$q->fetchColumn()>0)flash('This product has sales history and cannot be deleted. Set its stock to zero instead.','warning');else{$nameQ=$pdo->prepare('SELECT name FROM products WHERE id=? AND user_id=?');$nameQ->execute([$id,$uid]);$deletedName=(string)$nameQ->fetchColumn();$q=$pdo->prepare('DELETE FROM products WHERE id=? AND user_id=?');$q->execute([$id,$uid]);if($q->rowCount())audit_log($pdo,'product_deleted','product',(int)$id,'Product '.$deletedName);flash('Product removed.');}}redirect('products.php');}}
$q=$pdo->prepare('SELECT * FROM products WHERE user_id=? ORDER BY name');$q->execute([$uid]);$products=$q->fetchAll();$pageTitle='Products';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Products & inventory</h1><p class="muted mb-0">Keep prices, quantities, and reorder levels up to date.</p></div></div><?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?>
<div class="card mb-4"><div class="card-body p-4"><h2 class="h5 fw-bold mb-3">Add a product</h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="col-md-4"><label class="form-label">Product name</label><input class="form-control" name="name" maxlength="160" required></div><div class="col-md-2"><label class="form-label">SKU (optional)</label><input class="form-control" name="sku" maxlength="80"></div><div class="col-md-2"><label class="form-label">Cost price (₦)</label><input class="form-control" type="number" min="0" step="0.01" name="cost_price" required value="0"></div><div class="col-md-2"><label class="form-label">Selling price (₦)</label><input class="form-control" type="number" min="0" step="0.01" name="selling_price" required value="0"></div><div class="col-md-1"><label class="form-label">Qty</label><input class="form-control" type="number" min="0" name="quantity" required value="0"></div><div class="col-md-1"><label class="form-label">Alert at</label><input class="form-control" type="number" min="0" name="low_stock_threshold" required value="5"></div><div class="col-12"><button class="btn btn-primary">Save product</button></div></form></div></div>
<div class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Inventory (<?=$products?count($products):0?>)</h2><input id="tableSearch" class="form-control" style="max-width:260px" placeholder="Search products..."></div><div class="table-responsive"><table class="table" id="searchTable"><thead><tr><th>Product</th><th>SKU</th><th>Cost</th><th>Price</th><th>Qty</th><th>Stock status</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td class="fw-semibold"><?=e($p['name'])?></td><td><?=e($p['sku']??'—')?></td><td><?=money($p['cost_price'])?></td><td><?=money($p['selling_price'])?></td><td><?=(int)$p['quantity']?></td><td><?php if((int)$p['quantity']<=(int)$p['low_stock_threshold']):?><span class="badge text-bg-warning">Low stock</span><?php else:?><span class="badge text-bg-success">In stock</span><?php endif;?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="edit_product.php?id=<?=(int)$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Remove this product?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$products):?><div class="empty-state">No products yet. Add your first product above.</div><?php endif;?></div></div></div><script>document.getElementById('tableSearch')?.addEventListener('input',function(){const q=this.value.toLowerCase();document.querySelectorAll('#searchTable tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q));});</script><?php require __DIR__.'/includes/footer.php';?>
